    namespace Magics {
        uint64_t bishopAttacks[64][512];
        uint64_t rookAttacks[64][4096];
        uint64_t bishopMasks[64];
        uint64_t rookMasks[64];
        int bishopShifts[64];
        int rookShifts[64];
        uint64_t rayBetween[64][64];

        uint64_t getBishopMask(int sq) {
            uint64_t mask = 0;
            int r = sq / 8, f = sq % 8;
            for (int i = r + 1, j = f + 1; i <= 6 && j <= 6; ++i, ++j) mask |= (1ULL << (i * 8 + j));
            for (int i = r + 1, j = f - 1; i <= 6 && j >= 1; ++i, --j) mask |= (1ULL << (i * 8 + j));
            for (int i = r - 1, j = f + 1; i >= 1 && j <= 6; --i, ++j) mask |= (1ULL << (i * 8 + j));
            for (int i = r - 1, j = f - 1; i >= 1 && j >= 1; --i, --j) mask |= (1ULL << (i * 8 + j));
            return mask;
        }

        uint64_t getRookMask(int sq) {
            uint64_t mask = 0;
            int r = sq / 8, f = sq % 8;
            for (int i = r + 1; i <= 6; ++i) mask |= (1ULL << (i * 8 + f));
            for (int i = r - 1; i >= 1; --i) mask |= (1ULL << (i * 8 + f));
            for (int j = f + 1; j <= 6; ++j) mask |= (1ULL << (r * 8 + j));
            for (int j = f - 1; j >= 1; --j) mask |= (1ULL << (r * 8 + j));
            return mask;
        }

        uint64_t getBishopAttacksSlow(int sq, uint64_t blockers) {
            uint64_t attacks = 0;
            int r = sq / 8, f = sq % 8;
            for (int i = r + 1, j = f + 1; i <= 7 && j <= 7; ++i, ++j) { attacks |= (1ULL << (i * 8 + j)); if (blockers & (1ULL << (i * 8 + j))) break; }
            for (int i = r + 1, j = f - 1; i <= 7 && j >= 0; ++i, --j) { attacks |= (1ULL << (i * 8 + j)); if (blockers & (1ULL << (i * 8 + j))) break; }
            for (int i = r - 1, j = f + 1; i >= 0 && j <= 7; --i, ++j) { attacks |= (1ULL << (i * 8 + j)); if (blockers & (1ULL << (i * 8 + j))) break; }
            for (int i = r - 1, j = f - 1; i >= 0 && j >= 0; --i, --j) { attacks |= (1ULL << (i * 8 + j)); if (blockers & (1ULL << (i * 8 + j))) break; }
            return attacks;
        }

        uint64_t getRookAttacksSlow(int sq, uint64_t blockers) {
            uint64_t attacks = 0;
            int r = sq / 8, f = sq % 8;
            for (int i = r + 1; i <= 7; ++i) { attacks |= (1ULL << (i * 8 + f)); if (blockers & (1ULL << (i * 8 + f))) break; }
            for (int i = r - 1; i >= 0; --i) { attacks |= (1ULL << (i * 8 + f)); if (blockers & (1ULL << (i * 8 + f))) break; }
            for (int j = f + 1; j <= 7; ++j) { attacks |= (1ULL << (r * 8 + j)); if (blockers & (1ULL << (r * 8 + j))) break; }
            for (int j = f - 1; j >= 0; --j) { attacks |= (1ULL << (r * 8 + j)); if (blockers & (1ULL << (r * 8 + j))) break; }
            return attacks;
        }

        uint64_t set2bb(int index, int bits, uint64_t mask) {
            uint64_t result = 0;
            for (int i = 0; i < bits; ++i) {
                int sq = __builtin_ctzll(mask);
                mask &= mask - 1;
                if (index & (1 << i)) result |= (1ULL << sq);
            }
            return result;
        }

        void initRays() {
            for (int i = 0; i < 64; ++i) {
                for (int j = 0; j < 64; ++j) {
                    rayBetween[i][j] = 0;
                    if (i == j) continue;
                    int r1 = i / 8, f1 = i % 8, r2 = j / 8, f2 = j % 8;
                    int dr = r2 - r1, df = f2 - f1;
                    if (dr == 0 || df == 0 || std::abs(dr) == std::abs(df)) {
                        int stepR = (dr > 0) ? 1 : (dr < 0) ? -1 : 0;
                        int stepF = (df > 0) ? 1 : (df < 0) ? -1 : 0;
                        int curR = r1 + stepR, curF = f1 + stepF;
                        while (curR != r2 || curF != f2) {
                            rayBetween[i][j] |= (1ULL << (curR * 8 + curF));
                            curR += stepR; curF += stepF;
                        }
                    }
                    rayBetween[i][j] |= (1ULL << j); // Ray includes the target square!
                }
            }
        }

        void init() {
            static bool initialized = false;
            if (initialized) return;

            initRays();

            for (int sq = 0; sq < 64; ++sq) {
                bishopMasks[sq] = getBishopMask(sq);
                rookMasks[sq] = getRookMask(sq);
                bishopShifts[sq] = 64 - __builtin_popcountll(bishopMasks[sq]);
                rookShifts[sq] = 64 - __builtin_popcountll(rookMasks[sq]);

                int bBits = __builtin_popcountll(bishopMasks[sq]);
                for (int i = 0; i < (1 << bBits); ++i) {
                    uint64_t blockers = set2bb(i, bBits, bishopMasks[sq]);
                    uint64_t magicIdx = (blockers * Moves::BISHOP_MAGICS[sq]) >> bishopShifts[sq];
                    bishopAttacks[sq][magicIdx] = getBishopAttacksSlow(sq, blockers);
                }

                int rBits = __builtin_popcountll(rookMasks[sq]);
                for (int i = 0; i < (1 << rBits); ++i) {
                    uint64_t blockers = set2bb(i, rBits, rookMasks[sq]);
                    uint64_t magicIdx = (blockers * Moves::ROOK_MAGICS[sq]) >> rookShifts[sq];
                    rookAttacks[sq][magicIdx] = getRookAttacksSlow(sq, blockers);
                }
            }
            initialized = true;
        }
    }
